// Settings. The model drafts; an analyst accepts in Landledger. The cluster has no Anthropic credential, so the drafts come
// from the local Ollama model the cluster's agents use; change MODEL (and OLLAMA_URL) to use another.
const MODEL = 'qwen3-coder:30b';
const OLLAMA_URL = 'http://host.docker.internal:11434';  // Ollama on this machine, as the cluster reaches it
// Landledger records who drafted each note: this flow, as an agent, and the person who answers for it (empty: the
// notes key's minter). The sponsor never accepts the notes.
const AGENT = { id: `landflow:${$workflow.id}`, name: 'Variance note drafter', system: 'landflow' };
const SPONSOR = '';
return { ...$json, settings: { model: MODEL, ollamaUrl: OLLAMA_URL.replace(/\/+$/, ''), agent: AGENT, sponsor: SPONSOR } };

