// One item per note the month needs (the whole month, TOTAL, and each cost center), each with the figures it may cite
// and the prompt. Only for the snapshot that is still the month's: an old event (the snapshot moved on) drafts nothing.
const event = $('Settings').first().json;
const snapshot = $('Get the snapshot').first().json;
const figures = $input.first().json;
if (snapshot.sha256 !== figures.snapshotSha256 || event.snapshotSha256 !== figures.snapshotSha256 || snapshot.current === false) return [];
const money = (v) => (v === null || v === undefined ? null : Number(v).toFixed(2));
return (figures.needed ?? []).map((f) => {
  // Each figure as the exact cite to copy: a local model keeps to a menu far better than to names and values apart.
  const lines = [];
  const add = (figure, value, what) => { if (value !== null) lines.push(`- ${JSON.stringify({ figure, amount: value })}: ${what}`); };
  add('actual', money(f.actual), 'the month\'s cost');
  add('budget', money(f.budget), 'the month\'s budget');
  add('forecast_day10', money(f.forecastDay10), 'the forecast on day 10');
  // The direction in words, so a negative amount isn't read as a rise.
  const way = (v, less, more) => (v === null ? '' : Number(v) < 0 ? less : Number(v) > 0 ? more : 'no change');
  add('variance_budget', money(f.varianceBudget), `actual minus budget: ${way(f.varianceBudget, 'under budget', 'over budget')}`);
  add('variance_forecast', money(f.varianceForecast), `actual minus the day-10 forecast: ${way(f.varianceForecast, 'under the forecast', 'over the forecast')}`);
  for (const d of f.drivers ?? []) lines.push(`- ${JSON.stringify({ figure: `driver_${d.dimension}`, key: d.key, amount: money(d.change) })}: ${d.label} (${d.dimension}), its change on the month before: ${way(d.change, 'it cost less', 'it cost more')}`);
  const missing = [f.budget === null && 'no budget', f.forecastDay10 === null && 'no day-10 forecast'].filter(Boolean);
  const prompt = [
    `Month: ${event.month}`,
    `Cost center: ${f.costCenter === 'TOTAL' ? 'TOTAL (the month as a whole)' : `${f.costCenter} (${f.name})`}`,
    'FIGURES (USD), each as the cite to copy:',
    ...lines,
    ...(missing.length ? [`This cost center has ${missing.join(' and ')}: say so, don't invent one.`] : []),
  ].join('\n');
  return { json: {
    month: event.month,
    costCenter: f.costCenter,
    name: f.name,
    snapshotSha256: figures.snapshotSha256,
    prompt,
    model: event.settings.model,
    ollamaUrl: event.settings.ollamaUrl,
    agent: event.settings.agent,
    sponsor: event.settings.sponsor,
  } };
});

