// The model answers JSON { text, cites }, sometimes inside a code fence. A reply that isn't JSON goes as text without
// cites: Landledger's check (or the node's) decides, and a refusal gets one redraft.
const base = $('One note per cost center').item.json;
const raw = String($json.output ?? '').trim();
const body = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let parsed = null;
try { parsed = JSON.parse(body); } catch { const m = body.match(/\{[\s\S]*\}/); if (m) { try { parsed = JSON.parse(m[0]); } catch {} } }
const text = String(parsed?.text ?? raw).trim();
const cites = Array.isArray(parsed?.cites)
  ? parsed.cites.filter((c) => c && typeof c === 'object').map((c) => ({ figure: String(c.figure ?? ''), ...(c.key && String(c.figure).startsWith('driver_') ? { key: String(c.key) } : {}), amount: String(c.amount ?? '') }))
  : [];
return { ...base, text, cites };

// Submitted, or refused. A refusal of the draft itself (Landledger's 422: a cited figure differs from the snapshot; or
// the node's own check of the figures and text) gets one redraft with the refusal; anything else (409: the snapshot
// moved on, 401/403, Landledger down) gives up and leaves the note to Landledger's template.
const draft = $('Shape the draft').item.json;
const error = $json.error ? String($json.error.message ?? $json.error) : '';
if (!error) return { ...draft, route: 0, outcome: 'submitted', attempt: 1, noteId: $json.id ?? null, version: $json.versions?.at(-1)?.version ?? null, refusal: '' };
const retry = /Landledger API error 422|Cited figure|Text must be|Text is required/.test(error);
const retryPrompt = `${draft.prompt}\n\nLandledger refused your previous draft: ${error}\nYour previous draft: ${JSON.stringify({ text: draft.text, cites: draft.cites })}\nWrite it again. Copy each cite's JSON object from FIGURES exactly, and use no other number. Answer with JSON only.`;
return { ...draft, route: retry ? 1 : 0, outcome: retry ? 'redraft' : 'gave_up', attempt: 1, noteId: null, version: null, refusal: error, retryPrompt };

// The model answers JSON { text, cites }, sometimes inside a code fence. A reply that isn't JSON goes as text without
// cites: Landledger's check (or the node's) decides, and a refusal gets one redraft.
const base = $('Notes to redraft').item.json;
const raw = String($json.output ?? '').trim();
const body = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let parsed = null;
try { parsed = JSON.parse(body); } catch { const m = body.match(/\{[\s\S]*\}/); if (m) { try { parsed = JSON.parse(m[0]); } catch {} } }
const text = String(parsed?.text ?? raw).trim();
const cites = Array.isArray(parsed?.cites)
  ? parsed.cites.filter((c) => c && typeof c === 'object').map((c) => ({ figure: String(c.figure ?? ''), ...(c.key && String(c.figure).startsWith('driver_') ? { key: String(c.key) } : {}), amount: String(c.amount ?? '') }))
  : [];
return { ...base, text, cites };

// The redraft: submitted, or given up (one retry only). A note given up on is left to Landledger's template, which an
// analyst runs from the close (POST /api/notes/:month/template).
const draft = $('Shape the redraft').item.json;
const error = $json.error ? String($json.error.message ?? $json.error) : '';
if (!error) return { ...draft, outcome: 'submitted', attempt: 2, noteId: $json.id ?? null, version: $json.versions?.at(-1)?.version ?? null, refusal: draft.refusal };
return { ...draft, outcome: 'gave_up', attempt: 2, noteId: null, version: null, refusal: error };
